"""Declarative base shared by all ORM models."""

from sqlalchemy import MetaData
from sqlalchemy.orm import DeclarativeBase

# Explicit naming convention so every constraint gets a predictable name
# (e.g. "ix_app_state_key" not an autogenerated hash). Alembic's autogenerate
# diffs constraints by name, and unpredictable names produce spurious
# drop/create pairs across environments.
NAMING_CONVENTION = {
    "ix": "ix_%(table_name)s_%(column_0_name)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    """Base class for all ORM models. Import this, never sqlalchemy.orm directly."""

    metadata = MetaData(naming_convention=NAMING_CONVENTION)
